function frame(ms){const rawDt=last?Math.max(0,(ms-last)/1000):0;const dt=Math.min(rawDt,.05);last=ms;t+=dt;if(mode==='play'&&ready){walking=false;if(!blocked()){state.elapsed+=dt;const dx=joy.x+Number(keys.has('right'))-Number(keys.has('left')),dy=joy.y+Number(keys.has('down'))-Number(keys.has('up'));const beforeX=state.x,beforeY=state.y;walking=move(state,dx,dy,dt);if(walking&&t-spawnAt>1.2)guideUntil=Math.min(guideUntil,t+1.5);const travelled=Math.hypot(state.x-beforeX,state.y-beforeY);if(walking){walkPhase+=travelled/104;if(walkPhase-footAt>.39){footAt=walkPhase;beep(state.inside?75:55,.045,.012);}}tickCombat(state,combat,dt);if(Math.hypot(aim.x,aim.y)>.12||mouseAim){aimAngle(state,combat,aim.x,aim.y);const shot=fire(state,combat);if(shot){beep(shot.melee?80:115,shot.melee?.08:.14,shot.melee?.03:.1);if(shot.hit)beep(260,.06,.03);}}if(state.health<=0&&!downedShown){downedShown=true;persist();openPanel('downed');}if(t-saveAt>2){persist();saveAt=t;}updateHUD();}draw();$('guide').hidden=t>guideUntil||blocked();if(t>noticeUntil)$('notification').hidden=true;if(t>radioUntil)$('radio-message').hidden=true;$('diag').hidden=!prefs.fps;frameCount++;frameTime+=rawDt;if(frameTime>.7){$('fps').textContent=Math.round(frameCount/frameTime)+' FPS';frameCount=0;frameTime=0;}}requestAnimationFrame(frame);}
