// The shelter answers the last sortie in one line; the lamp burns once the garage battery came home.
function shelterMood(){const r=state.lastRun,n=r?countItems(r.carried):0;$('shelter').dataset.light=state.garageCompleted?'on':'off';$('shelter-light').textContent=state.garageCompleted?'Лампа горит: аккумулятор из гаража № 28 держит.':'Лампа не горит. Аккумулятор — в гараже № 28.';
 $('shelter-radio').textContent=!r?'Радио шипит на 104.7. Пока тихо.':r.outcome==='lost'?'Рюкзак остался там. Главное — ты дома.':r.location==='garages'&&r.carried.battery?'Лампа моргнула и загорелась. Принесено: '+n+' предм.':n?'Принесено: '+n+' предм. Разложи их на склад.':'Пустые руки, но живой.';}
function shelterNotice(text){$('shelter-notice').textContent=text;}
// Run result: what came home, or what stayed on the ground.
function showRunResult(){const r=state.lastRun,lost=r.outcome==='lost',info=locationInfo(r.location);$('rr-eyebrow').textContent='ИТОГ ВЫЛАЗКИ · '+info.short;$('rr-title').textContent=lost?'Вылазка сорвана.':'Ты дома.';const items=Object.entries(lost?r.lost:r.carried);
 $('rr-copy').textContent=lost?'Рюкзак остался на месте. Убежище и склад целы.':items.length?'Вынесено за вылазку:':'Ничего нового не вынесено, но ты вернулся живым.';fillGrid($('rr-items'),items,lost?0:4,null,null);$('rr-items').hidden=!items.length;
 $('rr-stats').textContent=['Убито заражённых: '+r.kills,'Урон: '+r.damage,'Время: '+Math.floor(r.seconds/60)+':'+String(r.seconds%60).padStart(2,'0'),(lost?'Потеряно на ':'Ценность: ')+r.value,r.healed?'Медпункт: +'+r.healed+' здоровья':''].filter(Boolean).join(' · ');
 r.seen=true;persist();network.reportRun(r);openPanel('run-result');}
$('rr-close').onclick=()=>{$('run-result').close();renderShelter();};
// Region map: two playable locations, the rest shown as not yet scouted.
const riskDots=n=>'●'.repeat(n)+'○'.repeat(3-n);
function depletionText(id){const d=state.world?.locations?.[id]?.depletion||0;return d<1?'нетронута':d<2?'обыскана':d<3?'истощена':'выпотрошена';}
function renderMap(){$('map-region').textContent=REGION.country+' · '+REGION.name;const svg=$('region-svg'),ns='http://www.w3.org/2000/svg';svg.replaceChildren?.();
 if(svg.namespaceURI===ns){const add=(tag,attrs)=>{const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);svg.append(e);};
  for(const [x,y,rx,ry] of [[18,22,14,10],[12,78,12,14],[86,58,10,16],[48,88,16,7]])add('ellipse',{cx:x,cy:y,rx,ry,class:'map-forest'});
  add('path',{d:'M0 64 C20 58 30 74 52 70 S82 48 100 52',class:'map-river'});add('path',{d:'M8 96 L30 70 L44 48 L60 36 L80 18',class:'map-rail'});
  for(const l of LOCATIONS)add('line',{x1:SHELTER_POINT.x,y1:SHELTER_POINT.y,x2:l.map.x,y2:l.map.y,class:l.playable?'map-road':'map-road far'});}
 const nodes=$('map-nodes');nodes.replaceChildren();const home=document.createElement('div');home.className='map-node home';home.style.left=SHELTER_POINT.x+'%';home.style.top=SHELTER_POINT.y+'%';home.textContent='УБЕЖИЩЕ';nodes.append(home);
 for(const l of LOCATIONS){const n=document.createElement('div');n.className='map-node'+(l.playable?' open':' locked')+' risk-'+l.risk;n.style.left=l.map.x+'%';n.style.top=l.map.y+'%';n.textContent=l.short;nodes.append(n);}
 const cards=$('map-cards');cards.replaceChildren();for(const l of LOCATIONS.filter(l=>l.playable)){const card=document.createElement('div');card.className='map-card';const h=document.createElement('h4');h.textContent=l.name;const meta=document.createElement('small');meta.textContent='СЕКТОР '+l.sector+' · '+l.kind.toUpperCase()+' · РИСК '+riskDots(l.risk)+' · '+depletionText(l.id);const p=document.createElement('p');p.textContent=l.hint+(state[l.quest.flag]?'':' Задание: '+l.quest.text.toLowerCase()+'.');
  const go=$('sortie-'+l.id);go.className='metal primary';go.textContent='ВЫЙТИ НА ВЫЛАЗКУ';card.append(h,meta,p,go);cards.append(card);}
 $('map-future').textContent='Ещё не разведано: '+LOCATIONS.filter(l=>!l.playable).map(l=>l.short.toLowerCase()).join(', ')+'. Чем дальше и крупнее место, тем выше риск и ценнее добыча.';}
function openMap(){resetInput();mode='map';showScreen('map');renderMap();}
function sortie(location){if(!startSortie(state,location))return;combat=createCombat();downedShown=false;shelterPick=null;$('shelter-notice').textContent='';moduleNotice('');persist();start();}
for(const l of LOCATIONS.filter(l=>l.playable)){const b=$('sortie-'+l.id);b.onclick=()=>sortie(l.id);}
$('map-open').onclick=openMap;$('map-back').onclick=openShelter;$('shelter-menu').onclick=()=>{persist();setMenu();};
$('evacuate').onclick=()=>{if(failSortie(state,{kills:killsHere()})){downedShown=false;persist();openShelter();}};
// Diagnostics for browser checks only: open the game with ?debug to expose read access to the state.
if(String(location.search||'').includes('debug'))window.__ds={state:()=>state,combat:()=>combat,cam:()=>cam};
preload();requestAnimationFrame(frame);
